public int camelcase(String s) {
    if (s.isEmpty()) {
        return 0;
    }
    int words = 1;
    for (int i = 0; i < s.length(); i++) {
        if (Character.isUpperCase(s.charAt(i))) {
            words++;
        }
    }
    return words;
}

